/*
 * XCloud360 — P6.2 h264dec: baseline H.264 decoder benchmark on Xenon.
 *
 * Purpose:
 *   Prove libavcodec (ffmpeg) H.264 decoder cross-compiled for libxenon
 *   actually decodes our GOLDEN STREAM and measure raw fps without SIMD
 *   (pure C reference implementation). Result is the P6 baseline: any
 *   later VMX128 optimization (P7/P8) is compared to this number.
 *
 * Input:
 *   uda:/stream.h264 — Annex-B H.264, CBP 3.1, 1280x720@60fps, GOP 2s,
 *   ~4.5Mbps, generated by ffmpeg synth (see tools/xcloud-capture/output/
 *   GOLDEN-synth-720p60-baseline/). Deploy via FTP to USB root.
 *
 * Output:
 *   Console text: per-frame decode time, average fps, first-frame YUV
 *   plane pointers/strides to prove decode produced real pixels.
 *
 * Reports:
 *   - Frame N: t_ms=X.XX (running mean)
 *   - Final:   frames=N, total=T ms, mean=X ms/frame, fps=YY.Y
 *
 * NOT rendering to screen yet — that's the shader path (P4 sequence).
 * This binary is CPU decode profiling only.
 */

#include <stdio.h>
#include <stdint.h>
#include <string.h>
#include <stdlib.h>

#include <xetypes.h>
#include <console/console.h>
#include <xenos/xenos.h>
#include <xenos/xenos_videomodes.h>
#include <xenon_soc/xenon_power.h>
#include <ppc/timebase.h>
#include <time/time.h>
#include <input/input.h>
#include <usb/usbmain.h>

#include <libavcodec/avcodec.h>
#include <libavutil/mem.h>
#include <libavutil/imgutils.h>

#ifndef XCLOUD360_BUILD_VERSION
#define XCLOUD360_BUILD_VERSION "0.1.0-h264dec"
#endif

extern const uint8_t embedded_stream[];
extern const size_t embedded_stream_len;

/* wall-clock in microseconds using PowerPC timebase (@50MHz on Xenon).
 * mftb ticks at CPU/64; libxenon exposes PPC_TIMEBASE_FREQ constant. */
static uint64_t now_us(void) {
    return mftb() / (PPC_TIMEBASE_FREQ / 1000000ULL);
}

/* Stream is embedded in .rodata to avoid needing a filesystem. See
 * source/embedded_stream.c (generated from tools/xcloud-capture/output/
 * GOLDEN-synth-720p60-baseline-5s/stream.h264 via xxd -i). */

int main(void) {
    xenos_init(VIDEO_MODE_HDMI_720P);
    console_init();
    xenon_make_it_faster(XENON_SPEED_FULL);
    usb_init();
    usb_do_poll();

    printf("\n\n==== XCloud360 H264 decoder benchmark v%s ====\n\n",
           XCLOUD360_BUILD_VERSION);
    printf("[stream] embedded: %zu bytes\n", embedded_stream_len);

    /* -------- ffmpeg init -------- */
    avcodec_register_all();
    AVCodec* codec = avcodec_find_decoder(CODEC_ID_H264);
    if (!codec) { printf("[err] H.264 decoder not found in libavcodec\n"); goto stop; }
    printf("[ff]  codec: %s (%s)\n", codec->name, codec->long_name ? codec->long_name : "");

    AVCodecContext* ctx = avcodec_alloc_context3(codec);
    if (!ctx) { printf("[err] alloc_context3 failed\n"); goto stop; }
    ctx->thread_count = 1;   /* single-thread baseline first */

    if (avcodec_open2(ctx, codec, NULL) < 0) {
        printf("[err] avcodec_open2 failed\n"); goto stop;
    }

    AVCodecParserContext* parser = av_parser_init(CODEC_ID_H264);
    if (!parser) { printf("[err] av_parser_init failed\n"); goto stop; }

    AVFrame* frame = avcodec_alloc_frame();
    AVPacket pkt;
    av_init_packet(&pkt);
    if (!frame) { printf("[err] av_frame_alloc failed\n"); goto stop; }

    /* -------- decode loop -------- */
    uint64_t t0 = now_us();
    uint64_t total_decode_us = 0;
    int frame_count = 0;
    const uint8_t* data = embedded_stream;
    size_t         left = embedded_stream_len;

    while (left > 0) {
        uint8_t* out_data = NULL;
        int out_size = 0;
        int used = av_parser_parse2(parser, ctx,
            &out_data, &out_size, (uint8_t*)data, left,
            AV_NOPTS_VALUE, AV_NOPTS_VALUE, 0);
        if (used < 0) { printf("[err] parser returned %d\n", used); break; }
        data += used; left -= used;
        if (out_size <= 0) continue;

        pkt.data = out_data;
        pkt.size = out_size;

        uint64_t t_dec_a = now_us();
        int got_frame = 0;
        int r = avcodec_decode_video2(ctx, frame, &got_frame, &pkt);
        uint64_t t_dec_b = now_us();
        if (r < 0) { printf("[err] decode returned %d at frame %d\n", r, frame_count); break; }

        if (got_frame) {
            total_decode_us += (t_dec_b - t_dec_a);
            frame_count++;
            if (frame_count == 1 || (frame_count % 60) == 0) {
                double running_ms = (double)total_decode_us / 1000.0 / frame_count;
                printf("[dec] frame %4d: %dx%d fmt=%d t_avg=%.2f ms/frame\n",
                       frame_count, frame->width, frame->height, frame->format,
                       running_ms);
            }
        }
    }

    /* flush */
    pkt.data = NULL; pkt.size = 0;
    int got_frame = 0;
    do {
        got_frame = 0;
        int r = avcodec_decode_video2(ctx, frame, &got_frame, &pkt);
        if (r < 0) break;
        if (got_frame) frame_count++;
    } while (got_frame);

    uint64_t t1 = now_us();
    double wall_s = (t1 - t0) / 1e6;
    double mean_ms = frame_count ? (double)total_decode_us / 1000.0 / frame_count : 0;
    double fps = frame_count / wall_s;

    printf("\n==== RESULT ====\n");
    printf("frames decoded : %d\n", frame_count);
    printf("wall time      : %.2f s\n", wall_s);
    printf("mean decode    : %.2f ms/frame\n", mean_ms);
    printf("effective fps  : %.2f\n", fps);
    printf("target         : 60.00 fps  (need mean <= 16.67 ms)\n");

    if (fps >= 55.0)      printf("verdict        : PASS (>= 55 fps, within ADR-002 tolerance)\n");
    else if (fps >= 30.0) printf("verdict        : PARTIAL (>= 30 fps, needs SIMD)\n");
    else                  printf("verdict        : FAIL (< 30 fps — SIMD mandatory)\n");

    av_free(frame); frame = NULL;
    avcodec_close(ctx);
    av_free(ctx);

stop:
    printf("\n[end] press A to exit\n");
    for (;;) {
        struct controller_data_s c;
        usb_do_poll();
        get_controller_data(&c, 0);
        if (c.a) break;
        udelay(20000);
    }
    return 0;
}
